//CUSTDATA EXEC PGM=IDCAMS,COND=(7,LT,DEFINE1)
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  REPRO                     -
    INFILE(DDIN)            -
    OUTFILE(DDOUT)
/*
//DDIN     DD DISP=SHR,DSN=<KSDSCUS>
//DDOUT    DD DISP=SHR,DSN=<USRHLQ>.GENAPP.KSDSCUST
//*
//POLYDATA EXEC PGM=IDCAMS,COND=(7,LT,DEFINE2)
